const pill=(s,c='')=>`<span class="pill ${c||(/ativa|Confirmado|Concluído|Enviado|andamento/.test(s)?'green':/Aguardando|Planejada|revisão/.test(s)?'amber':'')}">${esc(s)}</span>`;
const avatar=p=>`<span class="avatar" style="--av:${p.color||'#40557c'}">${esc(p.initials||p.owner||'AC')}</span>`;
const btn=(text,route,primary=false,ic='arrow')=>`<button class="btn ${primary?'primary':''}" data-nav="${route}">${esc(text)} ${icon(ic)}</button>`;
const heading=(title,desc,actions='')=>`<div class="page-heading"><div><p class="eyebrow">SEU WORKSPACE, CONECTADO.</p><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="actions">${actions}</div></div>`;
const tabs=(items,selected,attr='filter')=>`<div class="tabs">${items.map(x=>`<button data-${attr}="${esc(x)}" class="${x===selected?'selected':''}">${esc(x)}</button>`).join('')}</div>`;
const sectionHead=(title,link='',route='')=>`<div class="section-head"><h2>${title}</h2>${link?`<button class="page-link" data-nav="${route}">${link} ${icon('arrow')}</button>`:''}</div>`;
const notice=(s='Todos os registros desta versão são fictícios. Integrações, pagamentos e agentes não estão conectados.')=>`<div class="notice">${s}</div>`;
const metric=(label,value,change,ic='chart')=>`<div class="card"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value}</div><svg class="trend" viewBox="0 0 100 35"><path d="M0 30 12 25 23 28 35 16 46 22 59 12 70 16 83 6 100 2" fill="none" stroke="#8eb4ff" stroke-width="1.5"/></svg><div class="metric-foot"><span class="positive">↗ ${change}</span> vs. ciclo anterior · demo</div></div>`;
function chart(){return `<div class="chart" role="img" aria-label="Gráfico ilustrativo: médicos alcançados e conversas crescem durante o ciclo. Valores fictícios."><div class="chart-y"><span>500</span><span>375</span><span>250</span><span>125</span><span>0</span></div><svg viewBox="0 0 600 180" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#759ff5" stop-opacity=".25"/><stop offset="1" stop-color="#759ff5" stop-opacity="0"/></linearGradient></defs>${[5,47,89,131,175].map(y=>`<path d="M0 ${y}H600" stroke="#a5c4ee12" stroke-dasharray="3 5"/>`).join('')}<path d="M0 150C40 150 45 95 95 108S160 130 200 80 260 110 300 60 350 85 400 48 465 72 500 30 560 50 600 6V180H0Z" fill="url(#area)"/><path d="M0 150C40 150 45 95 95 108S160 130 200 80 260 110 300 60 350 85 400 48 465 72 500 30 560 50 600 6" fill="none" stroke="#93b6ff" stroke-width="2"/><path d="M0 170C60 160 70 153 100 159S170 150 200 141 250 149 300 128 360 140 400 112 460 121 500 99 560 113 600 80" fill="none" stroke="#76c8d3" stroke-width="1.7"/></svg><div class="chart-labels">${['01','05','10','15','20','25','30'].map(x=>`<span>${x} nov</span>`).join('')}</div></div><div class="chart-legend"><span><i></i>Médicos alcançados</span><span><i class="cyan"></i>Conversas iniciadas</span></div>`}
function ring(){return `<div class="ring-wrap"><div class="ring"><div><strong>1.248</strong><small>pessoas na operação</small></div></div><div class="legend">${[['#82acff','Em contato','38%'],['#6ed0d4','Qualificados','28%'],['#777acc','Parceria ativa','20%'],['#53617d','Onboarding','14%']].map(([c,s,v])=>`<div><span><i style="--dot:${c}"></i>${s}</span><span>${v}</span></div>`).join('')}</div></div>`}
function overview(){return heading('Tudo conectado. Mais possibilidades.','Uma visão clara da sua operação, com inteligência em cada etapa.',btn('Conheça o sistema','apresentacao',false,'orbit'))+`<div class="grid four">${metric('Pessoas na operação','1.248','23%','people')}${metric('Conversas no ciclo','432','18%','chat')}${metric('Parcerias ativas','86','12%','link')}${metric('Pedidos no ciclo','48','32%','box')}</div><div class="grid two mt"><section class="card">${sectionHead('A operação em movimento','Explorar indicadores','indicadores')}<div class="actions"><span class="pill">Novembro · ciclo demonstrativo</span></div>${chart()}</section><section class="card">${sectionHead('Relacionamentos que evoluem','Ver pessoas','pessoas')}${ring()}</section></div><div class="grid two mt"><section class="card">${sectionHead('Seu dia, em foco','Ver agenda','reunioes')}${[['09:00','video','Reunião com Dra. Juliana','Apresentação da parceria · 30 min','reunioes/juliana'],['11:00','pin','Visita à Dra. Marina','São Paulo · Ana Silva','visitas/marina'],['14:30','box','Preparar pedido #1043','Documentação conferida · demonstração','pedidos/1043']].map(([time,ic,t,s,r])=>`<button class="list-row" data-nav="${r}"><span class="tiny-icon">${icon(ic)}</span><span class="grow"><strong>${t}</strong><small>${s}</small></span><span class="activity-time">${time}</span></button>`).join('')}</section><section class="card">${sectionHead('O que acontece por aqui','Ver notificações','notificacoes')}${[['people','Nova parceria em demonstração','Dra. Marina Costa · Jornada médica','pessoas/marina'],['file','Documento aguardando conferência','Pedro Lima · Jornada do paciente','pessoas/pedro'],['brain','Manual disponível para revisão','Consultora de Médicos · versão 1.2','cerebro/manual-medico']].map(([ic,t,s,r])=>`<button class="list-row" data-nav="${r}"><span class="tiny-icon">${icon(ic)}</span><span class="grow"><strong>${t}</strong><small>${s}</small></span>${icon('arrow')}</button>`).join('')}</section></div><div class="insight"><div class="ai-orb">✧</div><p><strong>Uma equipe de IA. Um contexto compartilhado.</strong><br>Consultoras de Médicos e Pacientes conectadas ao Copilot da sua equipe.</p><button class="btn" style="margin-left:auto" data-open-copilot>Conversar com Copilot ${icon('sparkles')}</button></div>`}
function indicators(){return heading('Indicadores','Entenda os resultados e explore os registros por trás de cada número.',btn('Pessoas deste ciclo','pessoas'))+notice('Indicadores ilustrativos do ciclo de novembro. Não representam resultados comerciais reais.')+`<div class="grid four">${metric('Médicos alcançados','1.248','23%','people')}${metric('Conversas iniciadas','432','18%','chat')}${metric('Reuniões realizadas','64','12%','video')}${metric('Parcerias ativas','86','12%','link')}</div><div class="grid two mt"><div class="card">${sectionHead('Evolução do ciclo')}${chart()}</div><div class="card">${sectionHead('Distribuição por etapa')}${ring()}</div></div><div class="card mt">${sectionHead('Da estratégia ao relacionamento','Ver estratégia','estrategia')}<div class="grid four">${[['Abordagem',1248,100],['Em conversa',432,65],['Qualificados',218,40],['Parceria ativa',86,20]].map(([s,n,w])=>`<button data-nav="pessoas" style="text-align:left"><small>${s}</small><div class="metric-value">${n}</div><div class="progress" style="--progress:${w}%"><i></i></div><small>Ver população demonstrativa ↗</small></button>`).join('')}</div></div>`}
function strategy(){return heading('Estratégia','Direcione a aquisição. A inteligência cuida da continuidade.',`<button class="btn primary" data-edit="strategy">${icon('target')} Ajustar distribuição</button>`)+notice('Plano e capacidade ilustrativos: 500 novos médicos e até 25 segmentações por ciclo. Nenhuma prospecção real é executada.')+`<div class="grid two"><div class="card">${sectionHead('Cada conexão começa com direção')}<div class="ring-wrap" style="justify-content:center"><div class="ring" style="width:210px;height:210px"><div><strong>500</strong><small>médicos / ciclo</small></div></div></div><p style="text-align:center;font-size:11px">Distribuição de capacidade · plano demonstrativo</p></div><div class="card" id="strategy-distribution">${sectionHead('Segmentos prioritários')}${['Neurologia','São Paulo · capital','Psiquiatria','Outros segmentos'].map((name,i)=>[name,(saved.distribution||[30,25,25,20])[i],(saved.distribution||[30,25,25,20])[i]*5]).map(([s,p,n])=>`<div style="margin:20px 0"><div class="metric-label"><button data-nav="segmento/${encodeURIComponent(s)}">${s} ↗</button><span>${p}% · ${n} médicos</span></div><div class="progress" style="--progress:${p*2}%"><i></i></div></div>`).join('')}</div></div><div class="grid three mt">${[['target','Estratégia definida','O gestor orienta segmentos, capacidade e prioridades.'],['brain','Execução contextual','A pesquisa e qualificação pertencem à operação interna da Minerva.'],['people','Relações no workspace','As pessoas, conversas e resultados aparecem nas áreas correspondentes.']].map(([i,t,p])=>`<div class="card feature"><div class="feature-icon">${icon(i)}</div><h2>${t}</h2><p>${p}</p></div>`).join('')}</div>`}
function campaignPage(){let list=campaigns.filter(c=>(state.filter==='Todas'||c.status===state.filter)&&`${c.name} ${c.topic}`.toLowerCase().includes(state.query.toLowerCase()));return heading('Campanhas','Conteúdo, aquisição e relacionamento com um propósito em comum.',`<button class="btn primary" data-edit="campaign">${icon('plus')} Nova campanha</button>`)+tabs(['Todas','Em andamento','Planejada'],state.filter==='Todos'?'Todas':state.filter)+`<div class="toolbar"><input class="local-search" data-search="campaigns" placeholder="Buscar campanha…" value="${esc(state.query)}" aria-label="Buscar campanha"><small>${list.length} campanhas · demonstração</small></div><div class="grid three">${list.map(c=>`<article class="card"><div class="campaign-art" style="--art:${c.color}">${icon(c.icon)}</div><div class="campaign-meta">${pill(c.status)}<small>Jornada médica</small></div><h2>${esc(c.name)}</h2><p style="font-size:11px">${esc(c.topic)}</p><div class="campaign-stats"><div><strong>${c.leads}</strong><small>Pessoas</small></div><div><strong>${c.talks}</strong><small>Conversas</small></div><div><strong>${c.meetings}</strong><small>Reuniões</small></div></div><div class="mt">${btn('Explorar campanha',`campanhas/${c.id}`)}</div></article>`).join('')}</div>${list.length?'':'<div class="empty">Nenhuma campanha encontrada.</div>'}`}
function peoplePage(){const list=people.filter(p=>(state.filter==='Todos'||p.type===state.filter)&&`${p.name} ${p.specialty} ${p.city}`.toLowerCase().includes(state.query.toLowerCase()));return heading('Pessoas','Cada pessoa, uma história. Todo o contexto no mesmo lugar.',`<button class="btn primary" data-edit="person">${icon('plus')} Nova pessoa</button>`)+tabs(['Todos','Médico','Paciente'],state.filter)+`<div class="card"><div class="toolbar"><input class="local-search" data-search="people" value="${esc(state.query)}" placeholder="Buscar nome, especialidade ou cidade…" aria-label="Buscar pessoas"><small>${list.length} pessoas demonstrativas</small></div><div class="table-wrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Cidade</th><th>Etapa</th><th>Responsável</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><button class="person-cell table-link" data-nav="pessoas/${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><br><small>${esc(p.specialty)}</small></span></button></td><td>${p.type}</td><td>${esc(p.city)}</td><td>${pill(p.stage)}</td><td>${esc(p.owner)}</td><td><button class="icon-button" data-nav="pessoas/${p.id}" aria-label="Abrir ficha de ${esc(p.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<div class="empty">Nenhuma pessoa encontrada.</div>'}</div>`}
function personDetail(id){const p=people.find(p=>p.id===id);if(!p)return notFound();return heading('Ficha contextual','Contexto único, conectado a conversas e atividades.')+`<button class="back" data-nav="pessoas">${icon('back')} Todas as pessoas</button><div class="card"><div class="detail-top">${avatar(p)}<div><h2>${esc(p.name)}</h2><p class="subtitle">${esc(p.specialty)} · ${esc(p.city)}</p></div></div><div class="detail-grid"><div><small>Jornada</small><strong>${p.type==='Médico'?'Relacionamento médico':'Jornada do paciente'}</strong></div><div><small>Etapa atual</small><strong>${pill(p.stage)}</strong></div><div><small>Responsável</small><strong>${esc(p.owner)}</strong></div></div>${notice('Cadastro fictício de demonstração. Não contém documentação clínica ou dados pessoais reais.')}<h2>Contexto para continuar</h2><p>${p.type==='Médico'?'Profissional presente na carteira demonstrativa. A proposta de parceria, os interesses e as atividades ficam relacionados à mesma ficha. Reunião ou visita não comprova aceite.':'Pessoa encaminhada para acolhimento. A relação continua independente do estado de cada pedido. Documentos e pagamentos precisam de verificação por fontes autorizadas.'}</p><div class="actions">${btn('Abrir conversa',`conversas/${p.id}`)}${btn('Ver atividades',`atividades/${p.id}`)}${p.type==='Paciente'?btn('Pedidos relacionados','pedidos'):btn('Preparar reunião',`reunioes/${p.id}`)}<button class="btn" data-open-copilot>Entender com Copilot ${icon('sparkles')}</button></div></div><div class="card mt">${sectionHead('Memória e fontes')}<div class="list-row"><span class="tiny-icon">${icon('file')}</span><div><strong>Registro demonstrativo da jornada</strong><small>Fonte: base fictícia desta versão · análise e decisões reais indisponíveis</small></div></div><p style="font-size:11px">Nenhuma inferência clínica, confirmação de pagamento ou autorização é criada a partir do texto de uma conversa.</p></div>`}
function conversations(id){const p=people.find(p=>p.id===(id||state.conversation))||people[0];state.conversation=p.id;return heading('Conversas','Relações com continuidade, contexto e participação humana.')+notice('Conversa demonstrativa. Mensagens enviadas abaixo ficam apenas nesta sessão e não chegam ao WhatsApp.')+`<div class="split"><div class="card conversation-list">${people.map(x=>`<button class="list-row ${p.id===x.id?'selected':''}" data-nav="conversas/${x.id}">${avatar(x)}<span class="grow"><strong>${esc(x.name)}</strong><small>${x.type==='Médico'?'Consultora de Médicos':'Consultora de Pacientes'}</small></span></button>`).join('')}</div><div class="card message-area"><div class="section-head"><div><h2>${esc(p.name)}</h2><small>Conversa ilustrativa · ${esc(p.stage)}</small></div><button class="page-link" data-nav="pessoas/${p.id}">Ver ficha ${icon('arrow')}</button></div><div class="message-thread" id="message-thread"><div class="message outgoing">Olá! Sou a Consultora da Minerva. Podemos continuar nossa conversa por aqui?<small>Mensagem demonstrativa · 09:30</small></div><div class="message">Olá! Gostaria de conhecer melhor a proposta e os próximos passos.<small>Mensagem demonstrativa · 09:32</small></div><div class="message outgoing">Claro. Vou apresentar as informações e organizar o contexto para a nossa equipe. Como posso ajudar?<small>Mensagem demonstrativa · 09:33</small></div></div><form class="chat-form" id="conversation-form"><input aria-label="Mensagem demonstrativa" placeholder="Escreva uma mensagem de demonstração…" required maxlength="2000"><button aria-label="Adicionar mensagem demonstrativa">↑</button></form></div></div>`}
function meetings(id){if(id){const p=people.find(p=>p.id===id)||people[2];return heading('Preparação da reunião','Contexto para uma conversa humana mais próxima.')+`<button class="back" data-nav="reunioes">${icon('back')} Voltar à agenda</button><div class="card"><div class="detail-top">${avatar(p)}<div><h2>${esc(p.name)}</h2><p class="subtitle">Apresentação da parceria · reunião demonstrativa</p></div></div><div class="detail-grid"><div><small>Data e horário</small><strong>Terça-feira · 09:00–09:30</strong></div><div><small>Responsável</small><strong>${esc(p.owner)}</strong></div><div><small>Canal</small><strong>Videoconferência · não conectada</strong></div></div><h2>Pauta sugerida</h2><div class="step"><span class="num">01</span><div><h3>Conhecer o contexto profissional</h3><p>Interesses, dúvidas e expectativas em relação à parceria.</p></div></div><div class="step"><span class="num">02</span><div><h3>Apresentar a Minerva</h3><p>Sistemas, materiais e possibilidades de relacionamento.</p></div></div><div class="step"><span class="num">03</span><div><h3>Combinar próximos passos</h3><p>Registrar acordos e pendências, sem presumir aceite.</p></div></div><div class="actions">${btn('Abrir ficha',`pessoas/${p.id}`)}<button class="btn primary" data-edit="meeting-result">Registrar resultado</button></div></div>`}return heading('Reuniões','Presença humana nos momentos que fazem diferença.',`<button class="btn primary" data-edit="meeting">${icon('plus')} Agendar reunião</button>`)+`<div class="card calendar-container">${sectionHead('Sua semana','Ver pessoas','pessoas')}<div class="actions"><span class="pill">Semana demonstrativa · 02–06 novembro</span><span class="pill gray">Calendário não conectado</span></div><div class="calendar">${['','SEG 02','TER 03','QUA 04','QUI 05','SEX 06'].map(s=>`<div class="day">${s}</div>`).join('')}${[9,10,11,14,15,16].map((h,r)=>`<div>${h}:00</div>${Array.from({length:5},(_,d)=>`<div>${(r===0&&d===1)||(r===2&&d===3)||(r===4&&d===2)?`<button class="event ${d===3?'teal':''}" data-nav="reunioes/${d===1?'juliana':d===3?'rafael':'marina'}">${h}:00 · 30 min<br>${d===1?'Dra. Juliana':d===3?'Dr. Rafael':'Dra. Marina'}<br>Apresentação da parceria</button>`:''}</div>`).join('')}`).join('')}</div></div>`}
function visits(id){if(id)return heading('Ficha da visita','Preparação, presença e continuidade do relacionamento.')+`<button class="back" data-nav="visitas">${icon('back')} Voltar às visitas</button><div class="card"><h2>Visita à Dra. Marina Costa</h2><p>São Paulo · roteiro demonstrativo · Ana Silva</p><div class="detail-grid"><div><small>Situação</small><strong>Planejada</strong></div><div><small>Objetivo</small><strong>Relacionamento e materiais</strong></div><div><small>Local</small><strong>Endereço real não cadastrado</strong></div></div><h2>Antes de sair</h2><p>Consulte a ficha, confirme disponibilidade e revise as pendências. O roteiro ilustrado não representa geolocalização ou trajeto real.</p><div class="actions">${btn('Consultar ficha','pessoas/marina')}<button class="btn primary" data-edit="visit-result">Registrar resultado</button></div></div>`;return heading('Visitas','Mais contexto para estar perto de quem importa.',`<button class="btn primary" data-edit="visit">${icon('plus')} Planejar visita</button>`)+`<div class="grid two"><div class="card">${sectionHead('Território de relacionamento')}<div class="map"><svg viewBox="0 0 500 380"><path d="M125 240C120 120 260 210 280 100S390 90 390 200" fill="none" stroke="#8eb7ff" stroke-width="3" stroke-dasharray="7 5"/></svg>${[[25,63,1],[56,26,2],[78,53,3]].map(([x,y,n])=>`<button class="pin" style="left:${x}%;top:${y}%" data-nav="visitas/marina" aria-label="Visita ilustrativa ${n}"><span>${n}</span></button>`).join('')}<span class="map-label">Mapa conceitual · sem geolocalização real</span></div></div><div class="card">${sectionHead('Roteiro demonstrativo')}${[people[0],people[2],people[1]].map((p,i)=>`<button class="list-row" data-nav="visitas/${p.id}"><span class="tiny-icon">${i+1}</span><span class="grow"><strong>${p.name}</strong><small>${p.city} · ${10+i}:00</small></span>${pill('Planejada')}</button>`).join('')}<div class="insight"><div class="ai-orb">✧</div><p>O Copilot prepara contexto. A equipe confirma o roteiro e realiza a visita.</p></div></div></div>`}
function boards(){return heading('Quadros','Organize o trabalho sem perder o contexto.',`<button class="btn primary" data-edit="task">${icon('plus')} Nova tarefa</button>`)+notice('Tarefas demonstrativas são salvas neste navegador. Alterar uma tarefa não muda a etapa de médicos, pagamentos ou pedidos.')+`<div class="kanban">${['A fazer','Em andamento','Em revisão','Concluído'].map(stage=>`<section class="kanban-column"><h3>${stage}<span>${tasks.filter(t=>t.stage===stage).length}</span></h3>${tasks.map((t,i)=>t.stage===stage?`<button class="task-card" data-task="${i}"><span class="pill gray">Equipe</span><p>${esc(t.title)}</p><div class="actions"><span class="avatar">${esc(t.owner)}</span><small>Editar tarefa ↗</small></div></button>`:'').join('')}</section>`).join('')}</div>`}
function orderPage(){const list=orders.filter(o=>(state.filter==='Todos'||o.status===state.filter)&&`${o.id} ${people.find(p=>p.id===o.person).name}`.toLowerCase().includes(state.query.toLowerCase()));return heading('Pedidos','Da conferência à entrega. Cada estado, uma evidência.',`${btn('Catálogo','catalogo',false,'box')}${btn('Estoque','estoque',false,'layers')}`)+tabs(['Todos','Em preparação','Enviado','Aguardando pagamento'],state.filter)+`<div class="card"><div class="toolbar"><input class="local-search" data-search="orders" value="${esc(state.query)}" placeholder="Buscar pedido ou paciente…" aria-label="Buscar pedidos"><small>${list.length} pedidos fictícios</small></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Paciente</th><th>Produto</th><th>Valor</th><th>Pagamento</th><th>Operação</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><button class="table-link" data-nav="pedidos/${o.id}">#${o.id}</button></td><td><button class="table-link" data-nav="pessoas/${o.person}">${people.find(p=>p.id===o.person).name}</button></td><td>${o.product}</td><td>${o.price}</td><td>${pill(o.payment)}</td><td>${pill(o.status)}</td><td><button class="icon-button" data-nav="pedidos/${o.id}" aria-label="Abrir pedido ${o.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<div class="empty">Nenhum pedido encontrado.</div>'}</div>`}
function orderDetail(id){const o=orders.find(o=>o.id===id);if(!o)return notFound();return heading(`Pedido #${o.id}`,'Pagamento, preparação e envio são estados independentes.')+`<button class="back" data-nav="pedidos">${icon('back')} Todos os pedidos</button><div class="card">${notice()}<div class="detail-grid"><div><small>Paciente</small><strong><button class="table-link" data-nav="pessoas/${o.person}">${people.find(p=>p.id===o.person).name}</button></strong></div><div><small>Pagamento</small><strong>${pill(o.payment)}</strong></div><div><small>Operação</small><strong>${pill(o.status)}</strong></div></div><h2>Itens do pedido</h2><div class="list-row"><span class="tiny-icon">${icon('box')}</span><span class="grow"><strong>${o.product}</strong><small>1 unidade · produto ilustrativo</small></span><strong>${o.price}</strong></div><div class="grid two mt"><div><h3>Documentação</h3><p style="font-size:12px">Conferência demonstrativa. Documentos originais não estão armazenados nesta interface.</p></div><div><h3>Envio e rastreio</h3><p style="font-size:12px">${o.tracking?`Código fictício: ${esc(o.tracking)}`:'Ainda não há registro de despacho.'}</p></div></div><div class="actions">${btn('Detalhe de pagamento',`pagamento/${o.id}`)}${btn('Detalhe do envio',`envio/${o.id}`)}<button class="btn" data-edit="support">Abrir suporte</button></div></div>`}
function catalog(stock=false,client=false){return heading(client?'Catálogo do paciente':stock?'Estoque':'Catálogo',client?'Apresentação ilustrativa de produtos. Sem compra ou recomendação clínica.':stock?'Quantidades e movimentos com contexto e rastreabilidade.':'Produtos e informações comerciais da empresa.',client?'':btn(stock?'Ver catálogo':'Ver estoque',stock?'catalogo':'estoque'))+notice('Produtos, preços e quantidades fictícios para demonstrar o layout. Não constituem oferta ou indicação terapêutica.')+(stock?`<div class="card table-wrap"><table><thead><tr><th>Produto</th><th>Apresentação</th><th>Saldo demonstrativo</th><th>Movimentações</th></tr></thead><tbody>${products.map(p=>`<tr><td><button class="table-link" data-nav="produto/${p.id}">${p.name}</button></td><td>${p.presentation}</td><td>${p.qty} unidades</td><td><button class="btn" data-nav="movimentos/${p.id}">Consultar histórico</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="grid three">${products.map(p=>`<article class="card"><div class="product-art"><div class="bottle"></div></div><h2>${p.name}</h2><p style="font-size:11px">${p.presentation}</p><div class="section-head"><strong>${p.price}</strong>${pill('Ilustrativo','gray')}</div>${btn('Ver produto',`produto/${p.id}`)}</article>`).join('')}</div>`)}
function brainPage(){return heading('Cérebro empresarial','Conhecimento, identidade e memória. O contexto por trás da inteligência.',`<button class="btn" data-open-copilot>${icon('sparkles')} Explorar com Copilot</button>`)+`<div class="insight" style="margin:0 0 24px"><div class="ai-orb">✧</div><p><strong>Um cérebro. Três IAs. Uma operação conectada.</strong><br>A base Minerva se conecta à identidade da empresa e à memória das relações.</p></div><div class="grid three">${brain.map(([id,i,t,d,m])=>`<button class="card brain-card" data-nav="cerebro/${id}"><div class="feature-icon">${icon(i)}</div><h2>${t}</h2><p>${d}</p><div class="card-bottom"><span>${m}</span><span>Explorar ↗</span></div></button>`).join('')}</div>`}
function brainDetail(id){const b=brain.find(b=>b[0]===id);if(!b)return notFound();const content={identidade:['Aproximar pessoas com inteligência','A Minerva combina tecnologia, rede e dados para organizar a operação de empresas do mercado de cannabis medicinal. A identidade de cada empresa orienta linguagem, materiais e condições de atendimento.','Manter comunicação clara, acolhedora e contextual. Separar informação, análise, proposta e decisão.'], 'manual-medico':['Relacionamento que continua','A Consultora de Médicos apoia abordagem, coleta de contexto, apresentação de parceria, onboarding e relacionamento. Reuniões e visitas são opcionais conforme estratégia e interesse.','Aceite de parceria requer registro próprio. Agendamento e visita não substituem o aceite. Dúvidas e suporte não apagam a jornada.'],'manual-paciente':['Acolher, orientar e acompanhar','A Consultora de Pacientes organiza acolhimento, receita, documentação, pedido e acompanhamento. Avaliação e prescrição são da profissional habilitada.','Extração de documento não equivale a validação. Relato de pagamento não comprova confirmação financeira.'],'manual-equipe':['Cada pessoa com seu contexto','Gestor: estratégia, equipe, análise e aprimoramento. Representante: reuniões, visitas, suporte e relacionamento. Despachante: pagamento, pedido, entrega e estoque.','O Copilot adapta contexto à responsabilidade. A interface de demonstração não implementa autenticação nem autorização real.'],conhecimento:['Ciência com fonte e contexto','A base científica deve preservar origem, vigência e limites das evidências. Nenhum conteúdo clínico de referência foi importado para esta demonstração.','Não há recomendação terapêutica ou prescrição nesta interface.'],juridico:['Regulação sem atalhos','Conteúdo regulatório depende da modalidade real de fornecimento e da legislação vigente. Esta página demonstra a organização e não apresenta parecer jurídico.','Não há acervo jurídico validado nesta versão.'],memoria:['Continuidade sem perder a origem','Memória relaciona acontecimentos, pessoas e pendências. Fato confirmado, relato, inferência e sugestão permanecem distintos.','Os registros desta versão são fictícios e não representam histórico de atendimento real.'],decisoes:['Aprimoramento com evidência','Propostas mostram motivo, impacto e versão-base. Aprovação e aplicação são estados distintos. Experimentos precisam de população, período e indicador definido.','Não há experimento real ou conclusão causal nesta demonstração.'],fontes:['Originais preservados','Esta versão foi orientada pela documentação do repositório e pelo material Minerva Empresa — Neurum fornecido pelo proprietário.','Os documentos de produto são a referência funcional. O PDF é referência de apresentação e não comprova integrações implementadas.']};const c=content[id];return heading(b[2],b[3])+`<button class="back" data-nav="cerebro">${icon('back')} Cérebro empresarial</button><article class="card document"><span class="pill">${b[4]}</span><h2>${c[0]}</h2><p>${c[1]}</p><h2>Orientações e limites</h2><p>${c[2]}</p><h2>Fontes e situação</h2><p>Base: documentação de produto Minerva Empresa. Conteúdo de apresentação para demonstração; não é uma configuração publicada de agentes.</p><div class="actions">${btn('Ver fontes','fontes')}<button class="btn" data-edit="proposal">Propor alteração</button>${btn('Histórico de versões',`versoes/${id}`)}</div></article>`}
function management(){return heading('Gestão','Sua empresa, equipe e conexões. Cada acesso com responsabilidade.')+tabs(['Empresa','Equipe','Permissões','Conexões','Plano','Preferências'],state.tab,'tab')+`<div class="card">${({Empresa:`${sectionHead('Uma operação com identidade')}<div class="detail-top"><span class="avatar" style="width:60px;height:60px;font-size:18px">AC</span><div><h2>Aurora Cannabis</h2><p class="subtitle">Empresa fictícia · workspace de demonstração</p></div></div><div class="detail-grid"><div><small>Sistemas</small><strong>Médico e Paciente</strong></div><div><small>Perfil em exibição</small><strong>Gestor · demonstração</strong></div><div><small>Contexto</small><strong>Brasil · Português</strong></div></div>${btn('Identidade no Cérebro','cerebro/identidade')}`,Equipe:`${sectionHead('Pessoas que fazem acontecer')}<div class="table-wrap"><table><thead><tr><th>Colaborador fictício</th><th>Perfil</th><th>Situação</th></tr></thead><tbody>${[['Alex Costa','Gestor'],['Ana Silva','Representante'],['Bruno Costa','Representante'],['Diego Souza','Despachante']].map(([n,p])=>`<tr><td>${n}</td><td>${p}</td><td>${pill('Ativo na demo','green')}</td></tr>`).join('')}</tbody></table></div><p class="mt" style="font-size:11px">Convites e alteração de acessos dependem do serviço de autenticação. Não estão conectados nesta versão.</p>`,Permissões:`${sectionHead('Responsabilidades por perfil')}<div class="grid three">${[['Gestor','Estratégia, equipe, análise e aprimoramento.'],['Representante','Carteira atribuída, reuniões, visitas e suporte.'],['Despachante','Operação atribuída de pedidos, preparação, entrega e estoque.']].map(([t,d])=>`<div><h3>${t}</h3><p style="font-size:12px">${d}</p></div>`).join('')}</div>${notice('Esta é uma visão explicativa. Controle real de acesso exige validação no backend e não é implementado pelo navegador.')}`,Conexões:`${sectionHead('Canais e integrações')}${[['chat','WhatsApp · Consultora de Médicos'],['chat','WhatsApp · Consultora de Pacientes'],['sparkles','Telegram · Copilot'],['calendar','Calendário'],['box','Pagamentos e logística']].map(([i,t])=>`<div class="list-row"><span class="tiny-icon">${icon(i)}</span><span class="grow"><strong>${t}</strong><small>Configuração segura necessária no backend</small></span>${pill('Não conectado','gray')}</div>`).join('')}`,Plano:`${sectionHead('Capacidade demonstrativa')}<div class="grid three">${[['Aquisição mensal','500 médicos'],['Segmentações por ciclo','Até 25'],['Representantes','Até 25']].map(([s,n])=>`<div><small>${s}</small><div class="metric-value" style="font-size:25px">${n}</div></div>`).join('')}</div>${notice('Referência ilustrativa do briefing. Limites reais devem vir do contrato da empresa. Nenhuma cobrança ou contratação é realizada.')}`,Preferências:`${sectionHead('Sua experiência')}<p>Português do Brasil · Horários apresentados de forma ilustrativa.</p><button class="btn" id="reset-demo">Limpar tarefas salvas neste navegador</button><p class="mt" style="font-size:11px">A preferência de movimento reduzido do dispositivo é respeitada automaticamente.</p>`})[state.tab]}</div>`}
const slides=[['Sua operação, potencializada por uma equipe de IA.','Tecnologia que aproxima pessoas.','A Minerva conecta relacionamentos, conhecimento e execução para empresas do mercado de cannabis medicinal.'],['Um cérebro. Três IAs.','Uma operação conectada.','Consultora de Médicos, Consultora de Pacientes e Copilot compartilham o contexto da empresa, com responsabilidades distintas.'],['Relacionamento médico, com continuidade.','Sistema Médico','Da estratégia à abordagem, parceria e onboarding. A IA organiza o contexto; representantes participam onde a presença humana faz diferença.'],['Acolher. Orientar. Acompanhar.','Sistema Paciente','Do encaminhamento ao acompanhamento: receita, documentação, pedido e entrega organizados, com participação humana nos momentos necessários.'],['Sua equipe com mais contexto.','Copilot','Gestor, representante e despachante recebem apoio nas suas rotinas. Um Copilot, adaptado às responsabilidades de cada perfil.'],['O contexto por trás da inteligência.','Cérebro empresarial','Conhecimento científico e jurídico, identidade do negócio, manuais e memória das relações. Fontes, versões e decisões preservam o contexto.'],['Uma visão clara de toda a operação.','Workspace','Indicadores, estratégia, pessoas, conversas, agenda e pedidos conectados. Uma página por vez, com o Copilot ao seu lado.'],['Uma operação moldada à estratégia.','AI First','Operação digital contínua, equipe própria e rede de representantes podem ser combinadas. A estratégia orienta como humanos e inteligência trabalham juntos.']];
function presentation(){const s=slides[state.slide];return heading('Conheça a Minerva','Sistema Médico + Sistema Paciente + Copilot. Uma operação conectada.',btn('Abrir workspace','inicio',false,'arrow'))+`<section class="hero card"><div class="hero-copy"><p class="eyebrow">MINERVA EMPRESAS / ${s[1]}</p><h2 class="hero-title">${s[0]}</h2><p>${s[2]}</p><div class="actions"><button class="btn primary" data-slide="${(state.slide+1)%slides.length}">${state.slide===7?'Recomeçar apresentação':'Continuar apresentação'} ${icon('arrow')}</button>${btn('Explorar o sistema','inicio')}</div><div class="hero-note mt">${String(state.slide+1).padStart(2,'0')} / 08 &nbsp; · &nbsp; INTELIGÊNCIA EM TUDO.</div></div><div class="hero-visual" aria-hidden="true"><div class="orb">✧</div></div></section><div class="presentation-tabs" aria-label="Páginas da apresentação">${slides.map((s,i)=>`<button data-slide="${i}" class="${i===state.slide?'selected':''}" aria-label="Slide ${i+1}: ${s[1]}" ${i===state.slide?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><div class="grid three">${[['people','Consultora de Médicos','Prospecção orientada à estratégia, parceria e relacionamento.','cerebro/manual-medico'],['chat','Consultora de Pacientes','Acolhimento e acompanhamento da jornada, do início à continuidade.','cerebro/manual-paciente'],['sparkles','Copilot da equipe','Contexto e apoio para gestor, representante e despachante.','cerebro/manual-equipe']].map(([i,t,p,r])=>`<article class="card feature"><div class="feature-icon">${icon(i)}</div><h2>${t}</h2><p>${p}</p>${btn('Como funciona',r)}</article>`).join('')}</div><div class="notice mt">Apresentação baseada no material Minerva Empresa — Neurum. Esta nova interface é uma demonstração; operação autônoma e integrações precisam do backend CEBD.</div>`}
function notifications(){return heading('Notificações','O que aconteceu e o que precisa da sua atenção.',`<button class="btn" id="read-notifications">Marcar todas como lidas</button>`)+`<div class="card">${[['Proposta de ajuste do manual','Revisar linguagem de apresentação da parceria.','aprovacoes/manual'],['Documento aguardando conferência','Pedro Lima · contexto fictício de documentação.','pessoas/pedro'],['Preparar pedido #1043','Pagamento demonstrativo confirmado.','pedidos/1043']].map(([t,d,r])=>`<button class="list-row" data-nav="${r}"><span class="tiny-icon">${icon('bell')}</span><span class="grow"><strong>${t}</strong><small>${d}</small></span>${pill(state.read?'Lida':'Não lida',state.read?'gray':'')}${icon('arrow')}</button>`).join('')}</div><p class="fine-print">Marcar como lida não conclui uma tarefa nem aplica uma proposta.</p>`}
function contextual(type,id){if(type==='produto'){const p=products.find(p=>p.id===id);if(!p)return notFound();return heading(p.name,'Informações de apresentação do produto.')+`<button class="back" data-nav="catalogo">${icon('back')} Catálogo</button><div class="card"><div class="product-art"><div class="bottle"></div></div>${notice()}<div class="detail-grid"><div><small>Apresentação</small><strong>${p.presentation}</strong></div><div><small>Preço fictício</small><strong>${p.price}</strong></div><div><small>Disponibilidade demonstrativa</small><strong>${p.qty} unidades</strong></div></div><p>Ficha ilustrativa. Composição, documentação, fornecedor e condições reais não foram cadastrados. A interface não sugere troca ou equivalência terapêutica.</p><div class="actions">${btn('Consultar estoque','estoque')}${btn('Movimentações',`movimentos/${p.id}`)}</div></div>`}
if(type==='pagamento'||type==='envio'||type==='checkout'){const o=orders.find(o=>o.id===id);if(!o)return notFound();return heading(type==='envio'?'Envio e rastreio':type==='checkout'?'Pagamento do paciente':'Detalhe de pagamento',`Pedido demonstrativo #${o.id}`)+`<button class="back" data-nav="pedidos/${o.id}">${icon('back')} Voltar ao pedido</button><div class="card">${notice(type==='checkout'?'Prévia visual de pagamento. Sem checkout conectado, dados de cartão ou cobranças.':undefined)}<div class="detail-grid"><div><small>Situação</small><strong>${pill(type==='envio'?o.status:o.payment)}</strong></div><div><small>Referência</small><strong>#${o.id} · ${o.price}</strong></div><div><small>${type==='envio'?'Rastreio fictício':'Provedor'}</small><strong>${type==='envio'?(o.tracking||'Sem despacho'):'Não conectado'}</strong></div></div><p>${type==='envio'?'Preparação não equivale a despacho. Previsão não comprova entrega. Atualizações reais devem vir da operação logística.':'A situação é fictícia e não confirma transação real. Confirmação financeira deve vir de evidência do provedor.'}</p></div>`}
if(type==='segmento'){return heading(decodeURIComponent(id),'Segmentação demonstrativa da estratégia.')+`<button class="back" data-nav="estrategia">${icon('back')} Voltar à estratégia</button><div class="card"><h2>Prioridade do ciclo</h2><p>Critérios de segmentação orientam a aquisição. A pesquisa e a lista bruta de candidatos pertencem à operação interna da Minerva.</p><div class="actions">${btn('Ver pessoas','pessoas')}${btn('Ver indicadores','indicadores')}</div></div>`}
if(type==='aprovacoes')return heading('Proposta de alteração','Aprovar e aplicar são etapas diferentes.')+`<div class="card"><h2>Revisar apresentação da parceria</h2><p>Proposta fictícia para tornar a linguagem inicial mais clara e acolhedora.</p><div class="detail-grid"><div><small>Versão-base</small><strong>Manual Médico · v1.2</strong></div><div><small>Situação</small><strong>Rascunho demonstrativo</strong></div><div><small>Aplicação</small><strong>Não executada</strong></div></div><h3>Antes</h3><p>Apresentação genérica da empresa.</p><h3>Proposta</h3><p>Começar pelo contexto do profissional e apresentar a parceria conforme seu interesse.</p>${notice('Aprovação real exige identidade, autoridade, versão e execução no backend. Esta prévia não altera manuais.')}${btn('Consultar manual','cerebro/manual-medico')}</div>`;
if(type==='movimentos'){const p=products.find(p=>p.id===id);if(!p)return notFound();return heading('Movimentações',p.name)+`<button class="back" data-nav="estoque">${icon('back')} Estoque</button><div class="card">${notice('Histórico ilustrativo de composição do saldo. Não há movimentação real de mercadorias.')}<div class="list-row"><span class="tiny-icon">${icon('box')}</span><span class="grow"><strong>Saldo inicial demonstrativo</strong><small>Origem: dados fictícios da interface</small></span><strong>+${p.qty} unidades</strong></div></div>`}
if(type==='atividades'){const p=people.find(p=>p.id===id);if(!p)return notFound();return heading('Atividades',p.name)+`<button class="back" data-nav="pessoas/${id}">${icon('back')} Ficha contextual</button><div class="card">${[['file','Cadastro demonstrativo criado'],['chat','Conversa ilustrativa disponível'],['people','Responsável atribuído na demonstração']].map(([i,t])=>`<div class="list-row"><span class="tiny-icon">${icon(i)}</span><span><strong>${t}</strong><small>Fonte: base fictícia · sem evento real de backend</small></span></div>`).join('')}</div>`}
if(type==='fontes')return heading('Fontes e documentos','Referências usadas na construção desta versão.')+`<div class="card">${[['Briefing de contexto','00-contexto-minerva-para-replit.md'],['Especificação funcional','workspace-especificacao-funcional.md'],['Contexto e jornadas','minerva-contexto-e-jornadas.md'],['Apresentação Neurum','Minerva Empresa — Neurum · PDF fornecido pelo proprietário']].map(([t,d])=>`<div class="list-row"><span class="tiny-icon">${icon('file')}</span><span><strong>${t}</strong><small>${d}</small></span></div>`).join('')}</div>`;
if(type==='versoes')return heading('Histórico de versões','Referência editorial demonstrativa.')+`<div class="card"><h2>Versão de referência</h2><p>O conteúdo desta interface é uma apresentação baseada nos documentos de produto. Não existe histórico real de publicação de agentes conectado.</p>${btn('Voltar ao conteúdo',`cerebro/${id}`)}</div>`;
return notFound()}
function campaignDetail(id){const c=campaigns.find(c=>c.id===id);if(!c)return notFound();return heading(c.name,c.topic)+`<button class="back" data-nav="campanhas">${icon('back')} Todas as campanhas</button><div class="grid three">${metric('Pessoas',c.leads,'23%','people')}${metric('Conversas',c.talks,'18%','chat')}${metric('Reuniões',c.meetings,'12%','video')}</div><div class="card mt">${sectionHead('Contexto da campanha')}<p>Campanha demonstrativa de aquisição e relacionamento médico. Links, métricas e canais reais dependem das integrações autorizadas da empresa.</p><div class="detail-grid"><div><small>Situação</small><strong>${pill(c.status)}</strong></div><div><small>Público</small><strong>${esc(c.topic)}</strong></div><div><small>Canais</small><strong>Não conectados</strong></div></div><div class="actions">${btn('Pessoas relacionadas','pessoas')}${btn('Conversas','conversas')}<button class="btn" data-edit="campaign-edit">Editar apresentação</button></div></div>`}
function notFound(){return heading('Página não encontrada','Este recurso não faz parte dos dados demonstrativos.')+btn('Voltar à visão geral','inicio')}
function render(){const [r,id]=state.route.split('/');let content;switch(r){case'inicio':content=overview();break;case'indicadores':content=indicators();break;case'estrategia':content=strategy();break;case'campanhas':content=id?campaignDetail(id):campaignPage();break;case'pessoas':content=id?personDetail(id):peoplePage();break;case'conversas':content=conversations(id);break;case'reunioes':content=meetings(id);break;case'visitas':content=visits(id);break;case'quadros':content=boards();break;case'pedidos':content=id?orderDetail(id):orderPage();break;case'catalogo':content=catalog();break;case'estoque':content=catalog(true);break;case'catalogo-cliente':content=catalog(false,true);break;case'cerebro':content=id?brainDetail(id):brainPage();break;case'gestao':content=management();break;case'apresentacao':content=presentation();break;case'notificacoes':content=notifications();break;default:content=contextual(r,id)}document.getElementById('main').innerHTML=content;document.querySelectorAll('#navigation button').forEach(b=>{const active=b.dataset.nav===r;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.getElementById('copilot-context').textContent=`Contexto selecionado · ${pages.find(p=>p[0]===r)?.[2]||document.querySelector('h1')?.textContent||'Workspace'}`;document.title=`${document.querySelector('h1')?.textContent||'Workspace'} · Minerva`;}
function navigate(route){if(location.hash.slice(1)===route){state.route=route;state.filter=route==='campanhas'?'Todas':'Todos';state.query='';render()}else location.hash=route}
function routeFromHash(){state.route=location.hash.slice(1)||'inicio';state.filter=state.route==='campanhas'?'Todas':'Todos';state.query='';render();window.scrollTo(0,0)}
function toggleCopilot(open){document.getElementById('copilot').hidden=!open;document.getElementById('workspace').classList.toggle('has-copilot',open);document.getElementById('copilot-toggle').setAttribute('aria-expanded',String(open));if(open)document.getElementById('copilot-input').focus()}
let toastTimer;function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4000)}
function copilotMessage(text){const history=document.getElementById('copilot-history');const add=(message,cls)=>{const d=document.createElement('div');d.className=`chat-bubble ${cls}`;d.textContent=message;history.append(d)};add(text,'user');const q=text.toLowerCase();let match;if(/abr|mostr|ir para|ver /.test(q))match=[...pages,['catalogo','box','Catálogo'],['estoque','layers','Estoque'],['gestao','settings','Gestão'],['apresentacao','orbit','Apresentação']].find(([r,i,t])=>q.includes(t.toLowerCase())||q.includes(r));if(match){navigate(match[0]);add(`Abri ${match[2]} no painel principal e mantive esta conversa ao lado. Comando local de navegação; nenhuma ação de negócio foi executada.`,'ai')}else if(/expl|página|pagina|contexto/.test(q)){add(`Você está em ${document.querySelector('h1').textContent}. Esta página apresenta uma parte da operação Minerva com registros fictícios. Posso abrir Pessoas, Pedidos, Indicadores, Cérebro ou a Apresentação. Digite, por exemplo: “abra os pedidos”.`,'ai')}else add('Esta é uma demonstração local do Copilot, sem conexão com um modelo de IA. Posso abrir páginas por comandos como “abra pessoas” ou explicar a página atual. Mensagens, cobranças e mudanças de regras não são executadas.','ai');history.scrollTop=history.scrollHeight}
function search(){const q=document.getElementById('search-input').value.toLowerCase();const items=[...pages.map(([r,i,t])=>[r,i,t,'Página']),['gestao','settings','Gestão','Página'],['apresentacao','orbit','Apresentação','Página'],['catalogo','box','Catálogo','Página'],['estoque','layers','Estoque','Página'],['catalogo-cliente','box','Catálogo do paciente','Prévia'],['checkout/1043','box','Pagamento do paciente','Prévia'],...people.map(p=>[`pessoas/${p.id}`,'people',p.name,'Pessoa']),...orders.map(o=>[`pedidos/${o.id}`,'box',`Pedido #${o.id}`,'Pedido'])].filter(x=>x[2].toLowerCase().includes(q));document.getElementById('search-results').innerHTML=items.map(([r,i,t,k])=>`<button class="search-result" data-nav="${r}" data-close-search>${icon(i)}${esc(t)}<small>${k}</small></button>`).join('')||'<div class="empty">Nenhum resultado.</div>'}
function openEditor(kind,index){const dialog=document.getElementById('editor');const configs={task:['Nova tarefa','Título da tarefa'],person:['Nova pessoa demonstrativa','Nome'],campaign:['Nova campanha demonstrativa','Nome da campanha'],strategy:['Ajustar distribuição','Neurologia (%)'],meeting:['Agendar reunião demonstrativa','Título da reunião'],visit:['Planejar visita demonstrativa','Título da visita'],proposal:['Propor alteração','Resumo da proposta'],support:['Abrir suporte demonstrativo','Motivo do suporte'],'meeting-result':['Resultado da reunião','Resumo do resultado'],'visit-result':['Resultado da visita','Resumo do resultado'],'campaign-edit':['Editar apresentação','Nome da campanha']};let [title,label]=configs[kind]||['Editar tarefa','Título da tarefa'];const task=kind==='task-edit'?tasks[index]:null;dialog.innerHTML=`<form id="editor-form" data-kind="${kind}" data-index="${index??''}"><div class="dialog-top"><strong>${title}</strong><button type="button" class="icon-button" data-close-editor aria-label="Fechar">×</button></div><p style="font-size:11px">Edição de demonstração. Nenhuma integração externa é acionada.</p>${kind==='strategy'?['Neurologia','São Paulo · capital','Psiquiatria','Outros segmentos'].map((s,i)=>`<label>${s} (%)<input type="number" name="segment${i}" min="0" max="100" value="${[30,25,25,20][i]}" required></label>`).join(''):`<label>${label}<input name="title" required maxlength="150" value="${esc(task?.title||'')}"></label>`}${kind==='task-edit'?`<label>Situação<select name="stage">${['A fazer','Em andamento','Em revisão','Concluído'].map(s=>`<option ${s===task.stage?'selected':''}>${s}</option>`).join('')}</select></label>`:''}<p class="fine-print" style="text-align:left;margin-bottom:16px">${kind==='task'||kind==='task-edit'?'Tarefas são persistidas neste navegador.':'Este registro será mantido apenas nesta sessão.'}</p><button class="btn primary" type="submit">Salvar demonstração</button><p id="form-error" role="alert"></p></form>`;dialog.showModal()}
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));document.getElementById('navigation').innerHTML=pages.map(([r,i,t])=>`<button data-nav="${r}" title="${t}" aria-label="${t}">${icon(i)}<span class="nav-label">${t}</span></button>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){if(b.hasAttribute('data-close-search'))document.getElementById('search-dialog').close();navigate(b.dataset.nav)}if(b.hasAttribute('data-open-copilot'))toggleCopilot(true);if(b.dataset.filter){state.filter=b.dataset.filter;render()}if(b.dataset.tab){state.tab=b.dataset.tab;render()}if(b.dataset.slide!==undefined){state.slide=Number(b.dataset.slide);render()}if(b.dataset.edit)openEditor(b.dataset.edit);if(b.dataset.task!==undefined)openEditor('task-edit',Number(b.dataset.task));if(b.hasAttribute('data-close-editor'))document.getElementById('editor').close();if(b.dataset.prompt){toggleCopilot(true);copilotMessage(b.dataset.prompt)}if(b.id==='copilot-toggle')toggleCopilot(document.getElementById('copilot').hidden);if(b.id==='copilot-close')toggleCopilot(false);if(b.id==='search-open'){document.getElementById('search-dialog').showModal();search();document.getElementById('search-input').focus()}if(b.id==='read-notifications'){state.read=true;document.querySelector('.notification-dot').hidden=true;render();toast('Avisos marcados como lidos. As tarefas continuam abertas.')}if(b.id==='reset-demo'){try{localStorage.removeItem('minerva-aurora-demo')}catch{}toast('Tarefas salvas removidas. Recarregue para restaurar a demonstração.')}});
document.addEventListener('input',e=>{if(e.target.id==='search-input')search();if(e.target.dataset.search){const input=e.target,pos=input.selectionStart;state.query=input.value;render();const next=document.querySelector('[data-search]');next.focus();next.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='copilot-form'){e.preventDefault();const input=document.getElementById('copilot-input');if(input.value.trim())copilotMessage(input.value.trim());input.value=''}if(e.target.id==='conversation-form'){e.preventDefault();const input=e.target.querySelector('input');if(!input.value.trim())return;const message=document.createElement('div');message.className='message outgoing';message.textContent=input.value;const small=document.createElement('small');small.textContent='Rascunho demonstrativo · não enviado';message.append(small);document.getElementById('message-thread').append(message);input.value=''}if(e.target.id==='editor-form'){e.preventDefault();const form=e.target,data=new FormData(form),kind=form.dataset.kind,title=String(data.get('title')||'').trim();if(kind!=='strategy'&&!title){document.getElementById('form-error').textContent='Preencha um título válido.';return}if(kind==='task'){tasks.push({title,stage:'A fazer',owner:'AC'});persist()}else if(kind==='task-edit'){Object.assign(tasks[Number(form.dataset.index)],{title,stage:data.get('stage')});persist()}else if(kind==='person'){people.push({id:`local-${Date.now()}`,name:title,initials:title.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase(),type:'Médico',specialty:'Não informado',city:'Não informada',stage:'Cadastro demonstrativo',owner:'Não atribuído'})}else if(kind==='campaign'){campaigns.push({id:`local-${Date.now()}`,name:title,topic:'Público não definido',leads:0,talks:0,meetings:0,status:'Planejada',color:'#3c5678',icon:'campaign'})}else if(kind==='strategy'){const values=[0,1,2,3].map(i=>Number(data.get(`segment${i}`)));if(values.reduce((a,b)=>a+b,0)!==100){document.getElementById('form-error').textContent='A distribuição precisa somar 100%.';return}saved.distribution=values}else if(kind==='campaign-edit'){const c=campaigns.find(c=>c.id===state.route.split('/')[1]);if(c)c.name=title}else{saved.records=saved.records||[];saved.records.push({kind,title});}
document.getElementById('editor').close();render();if(kind==='strategy'){const names=['Neurologia','São Paulo · capital','Psiquiatria','Outros segmentos'];document.getElementById('strategy-distribution').innerHTML=sectionHead('Distribuição ajustada · nesta sessão')+saved.distribution.map((p,i)=>`<div style="margin:20px 0"><div class="metric-label"><span>${names[i]}</span><span>${p}% · ${p*5} médicos</span></div><div class="progress" style="--progress:${p}%"><i></i></div></div>`).join('')}if(!['task','task-edit','person','campaign','strategy','campaign-edit'].includes(kind)){openRecord(title)}else toast('Demonstração salva. Nenhuma ação externa foi executada.')}});
function openRecord(title){const dialog=document.getElementById('editor');dialog.innerHTML=`<div class="dialog-top"><strong>Registro demonstrativo criado</strong><button class="icon-button" data-close-editor aria-label="Fechar">×</button></div><h2>${esc(title)}</h2><p>O registro foi anotado nesta sessão. Calendário, canais, aprovações e regras de jornada não foram alterados.</p><h3>Registros desta sessão</h3>${saved.records.map(r=>`<div class="list-row"><span>${esc(r.title)}</span><small style="margin-left:auto">${esc(r.kind)}</small></div>`).join('')}`;dialog.showModal()}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('search-open').click()}if(e.key==='Escape'&&!document.getElementById('copilot').hidden&&!document.querySelector('dialog[open]'))toggleCopilot(false)});window.addEventListener('hashchange',routeFromHash);routeFromHash();
